/* Styled components & design primitives */
@layer say.components { /* Say CSS — styled components & design primitives.
   Layer: say.components. Override tokens with --say-* variables. */
@layer say.components {
  /* ---------- Layout primitives ---------- */
  .bento {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 1rem;
  }
  .bento > * { min-width: 0; }
  @media (max-width: 768px) {
    .bento { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  }
  @media (max-width: 480px) {
    .bento { grid-template-columns: 1fr; }
  }
  .bento-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bento-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .col-span-2 { grid-column: span 2 / span 2; }
  .col-span-3 { grid-column: span 3 / span 3; }
  .row-span-2 { grid-row: span 2 / span 2; }
  @media (max-width: 768px) {
    .col-span-2, .col-span-3, .row-span-2 { grid-column: auto; grid-row: auto; }
  }

  .container {
    width: 100%;
    margin-inline: auto;
    padding-inline: 1rem;
    max-width: 80rem;
  }
  .container-narrow { max-width: 48rem; }
  .container-wide { max-width: 96rem; }
  .section { padding-block: 4rem; }
  .stack { display: flex; flex-direction: column; gap: 1rem; }
  .cluster { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: center; }
  .center { display: grid; place-items: center; }

  /* ---------- Surface / card ---------- */
  .card {
    background: var(--say-color-card);
    color: var(--say-color-card-foreground);
    border: 1px solid color-mix(in oklab, var(--say-color-border) 80%, transparent);
    border-radius: 1rem;
    box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.04), 0 1px 3px 0 rgb(0 0 0 / 0.06);
    overflow: hidden;
    transition: box-shadow var(--say-duration-200) var(--say-ease-out),
                transform var(--say-duration-200) var(--say-ease-out),
                border-color var(--say-duration-200) var(--say-ease-out);
  }
  .card:hover { box-shadow: 0 8px 24px -4px rgb(0 0 0 / 0.08), 0 2px 8px -2px rgb(0 0 0 / 0.04); border-color: color-mix(in oklab, var(--say-color-border) 60%, transparent); }
  .card-interactive:hover { transform: translateY(-2px); }
  .card-elevated { box-shadow: var(--say-shadow-md); }
  .card-interactive:hover { transform: translateY(-2px); box-shadow: var(--say-shadow-xl); }
  .card-glass {
    background: color-mix(in oklab, var(--say-color-bg) 70%, transparent);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-color: color-mix(in oklab, var(--say-color-border) 60%, transparent);
  }
  .card-header {
    padding: 1.25rem 1.5rem;
    border-bottom: 1px solid var(--say-color-border);
    font-weight: var(--say-font-weight-semibold);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .card-body { padding: 1.5rem; }
  .card-footer {
    padding: 1.25rem 1.5rem;
    border-top: 1px solid var(--say-color-border);
    background: var(--say-color-bg-subtle);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  /* ---------- Buttons ---------- */
  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    font-weight: var(--say-font-weight-medium);
    line-height: 1;
    text-decoration: none;
    border: 1px solid transparent;
    border-radius: 0.625rem;
    padding: 0.5625rem 1.125rem;
    cursor: pointer;
    user-select: none;
    letter-spacing: -0.01em;
    transition: background-color var(--say-duration-150) var(--say-ease-out),
                color var(--say-duration-150) var(--say-ease-out),
                border-color var(--say-duration-150) var(--say-ease-out),
                box-shadow var(--say-duration-150) var(--say-ease-out),
                transform var(--say-duration-150) var(--say-ease-out);
  }
  .btn:hover { transform: translateY(-1px); }
  .btn:active { transform: translateY(0) scale(0.98); }
  .btn:active { transform: translateY(0); }
  .btn:focus-visible {
    outline: 2px solid var(--say-color-ring);
    outline-offset: 2px;
  }
  .btn:disabled,
  .btn[aria-disabled="true"] {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
    pointer-events: none;
  }
  .btn-sm { padding: 0.375rem 0.875rem; font-size: var(--say-text-sm); border-radius: var(--say-radius-md); }
  .btn-lg { padding: 0.875rem 1.75rem; font-size: var(--say-text-lg); border-radius: var(--say-radius-xl); }
  .btn-xl { padding: 1.125rem 2.25rem; font-size: var(--say-text-xl); border-radius: var(--say-radius-xl); }
  .btn-icon { padding: 0.625rem; aspect-ratio: 1; }
  .btn-block { width: 100%; }

  .btn-primary {
    background: linear-gradient(135deg, var(--say-color-primary-500), var(--say-color-primary-600));
    color: #fff;
    box-shadow: 0 6px 16px -4px color-mix(in oklab, var(--say-color-primary-500) 45%, transparent);
  }
  .btn-primary:hover {
    background: linear-gradient(135deg, var(--say-color-primary-600), var(--say-color-primary-700));
