    box-shadow: 0 6px 16px -4px color-mix(in oklab, var(--say-color-red-500) 45%, transparent);
  }
  .btn-danger:hover {
    background: linear-gradient(135deg, var(--say-color-red-600), var(--say-color-red-700));
